contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes assets and receiver address
    // We will call deposit(assets, receiver) from this contract (msg.sender == InvMutTest)
    // The general rule asserted:
    // If deposit returns (i.e., does not revert) then msg.sender==receiver must have held for the call (the withApproval modifier requires that),
    // and the returned shares equals the value returned by calling investment-manager-proxy view convertToShares(assets) via c.convertToShares(assets).
    // Because we may not know investmentManager internals, we assert consistency: when deposit succeeds, shares == c.convertToShares(assets).

    function run(uint256 assets, address receiver) public payable {
        require(true);

        // read view value before the state-changing call
        uint256 beforeTotalAssets = c.totalAssets();
        uint256 previewShares = c.convertToShares(assets);

        bool reverted;
        uint256 returnedShares = 0;
        // deposit is protected by withApproval(receiver) which requires msg.sender == receiver
        // Our contract is msg.sender for calls, so deposit should revert unless receiver == address(this)
        try c.deposit{value: 0}(assets, receiver) returns (uint256 shares) {
            reverted = false;
            returnedShares = shares;
        } catch {
            reverted = true;
        }

        // After call we can observe totalAssets again
        uint256 afterTotalAssets = c.totalAssets();

        // General rule asserted:
        // - If deposit reverted, then it must be because msg.sender != receiver (the modifier), so receiver != address(this)
        // - If deposit succeeded (not reverted), then receiver == address(this) and the returned shares equal c.convertToShares(assets)
        // Also require that totalAssets is unchanged when deposit reverts.
        assert(
            (
                reverted && receiver != address(this) && afterTotalAssets == beforeTotalAssets
            ) || (
                !reverted && receiver == address(this) && returnedShares == previewShares
            )
        );
    }

    receive() external payable { }
}

