contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that attempts to call updatePrice via auth: the test contract is the deployer of C
    function run(uint128 price) public payable {
        require(true);

        // pre-check readable values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // try to call updatePrice; InvMutTest is the deployer of C so it should be authorized
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // General rule: if the call did not revert, latestPrice equals the input price and lastPriceUpdate is nonzero and at least the previous timestamp
        // If the call reverted, state must be unchanged (conservative observable rule): latestPrice and lastPriceUpdate remain equal to before-values
        assert((!reverted && afterPrice == price && afterTimestamp != 0 && afterTimestamp >= beforeTimestamp) || (reverted && afterPrice == beforePrice && afterTimestamp == beforeTimestamp));
    }

    receive() external payable {}
}

