contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test entry. We attempt deposit and withdraw flows through c and assert a general invariant:
    // For arbitrary assets and receiver/owner addresses, calling deposit or withdraw either reverts or returns normally
    // and any successful call does not change totalAssets in a way inconsistent with convert/preview helpers —
    // here we assert a weaker but general property: if deposit succeeds it returns a shares value equal to previewDeposit(assets)
    // called from the same msg.sender context (previewDeposit is view and uses msg.sender), otherwise nothing observable changes.
    // We adapt by trying both deposit and mint entry points and check consistency with their preview helpers.

    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0));

        // snapshot observable before state
        uint256 beforeTotalAssets = c.totalAssets();
        uint256 beforeTotalSupply = c.totalSupply();

        // compute preview for deposit as msg.sender = this contract
        uint256 previewShares = c.previewDeposit(assets);

        // attempt deposit(assets, receiver) from this contract
        bool depositReverted;
        uint256 depositReturnedShares = type(uint256).max;
        try c.deposit(assets, receiver) returns (uint256 shares) {
            depositReverted = false;
            depositReturnedShares = shares;
        } catch {
            depositReverted = true;
        }

        // snapshot after first attempt
        uint256 midTotalAssets = c.totalAssets();
        uint256 midTotalSupply = c.totalSupply();

        // Now attempt a withdraw of the same assets to the same receiver with owner = receiver; this requires withApproval(owner) so it will likely revert unless receiver==address(this)
        bool withdrawReverted;
        uint256 withdrawReturnedShares = type(uint256).max;
        try c.withdraw(assets, receiver, receiver) returns (uint256 shares) {
            withdrawReverted = false;
            withdrawReturnedShares = shares;
        } catch {
            withdrawReverted = true;
        }

        // snapshot after withdraw attempt
        uint256 afterTotalAssets = c.totalAssets();
        uint256 afterTotalSupply = c.totalSupply();

        // General rule asserted:
        // If deposit succeeded then the returned shares must equal previewDeposit(assets) (both called from this contract as msg.sender),
        // and totalAssets/totalSupply may have changed (we do not assert precise deltas). If deposit reverted then totalAssets and totalSupply remain unchanged from before.
        // Additionally, withdraw either reverts or returns some shares; if withdraw succeeded it must not have changed totalAssets in a way incompatible with it being callable (we only assert if it reverted then state unchanged from mid snapshot).

        assert(
            // deposit branch: success -> returned shares equal preview
            (!depositReverted && depositReturnedShares == previewShares) 
            ||
            // deposit reverted branch: global observables unchanged
            (depositReverted && midTotalAssets == beforeTotalAssets && midTotalSupply == beforeTotalSupply)
        );

        // Also assert similar for withdraw w.r.t the mid snapshot: either withdraw reverted and state unchanged, or it succeeded (no further constraint here)
        assert(
            withdrawReverted ? (afterTotalAssets == midTotalAssets && afterTotalSupply == midTotalSupply) : true
        );
    }

    // No special receive logic needed
    receive() external payable {}
}

