contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes caller address to attempt mint for, recipient, and amount
    function run(address caller, address recipient, uint256 amount) public payable {
        require(caller != address(0) && recipient != address(0));

        // read totalSupply before
        uint256 ts_before = c.totalSupply();

        // Try calling mint as this contract (which is the deployer/ward initially because checker deploys fresh C -> constructor set wards[msg.sender]=1)
        // We need to detect whether msg.sender (this contract) is currently authorized in c.
        // The Auth.wards mapping is public, so wards getter exists. Use that to decide expected behavior.
        // However wards is declared in Auth and is public: getter is wards(address) -> uint256.
        uint256 myWard = Auth(address(c)).wards(address(this));

        bool reverted;
        try c.mint(amount, recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ts_after = c.totalSupply();

        // General rule:
        // If this contract was not authorized (wards[this]==0) then mint must revert and totalSupply must be unchanged.
        // If authorized (wards[this]==1) then mint must NOT revert. When authorized, totalSupply must be >= before (mint should not decrease totalSupply).
        assert(
            (myWard == 0 ? (reverted == true && ts_after == ts_before) : (reverted == false && ts_after >= ts_before))
        );
    }

    receive() external payable {}
}

