contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller (address of an authorized ward), price to set
    // We cannot change msg.sender of this contract when calling c, so to become authorized
    // we use c.rely(address(this)) but rely requires auth; however constructor of C set deployer as ward
    // The InvMutTest contract deployed C (per problem statement), so the initial ward is msg.sender of constructor
    // which was the test deployer, not this contract. Therefore we cannot rely on external wards.
    // Instead, we will observe two behaviors: when calling updatePrice from this contract it either
    // succeeds (meaning this contract is authorized) and then latestPrice equals the input and
    // lastPriceUpdate equals block.timestamp; or it reverts (not authorized). We assert that exactly one
    // of these holds: success implies both state updates, failure implies latestPrice unchanged and
    // lastPriceUpdate unchanged.

    function run(uint128 price) public payable {
        // read before values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule:
        // If the call succeeded (not reverted) then latestPrice equals the provided price and
        // lastPriceUpdate equals the current block.timestamp (i.e., afterTs == block.timestamp).
        // If the call reverted then both latestPrice and lastPriceUpdate remain unchanged.
        // We express this as a single assert combining both branches.
        assert(
            (!reverted && afterPrice == price && afterTs == block.timestamp)
            || (reverted && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    receive() external payable {}
}

