contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising deposit path and asserting a general invariant
    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0), "receiver-zero");
        // read view values before state-changing call
        uint256 beforeTotalAssets = c.totalAssets();
        uint256 previewShares = c.previewDeposit(assets);
        uint256 maxDep = c.maxDeposit(receiver);

        bool reverted;
        uint256 returnedShares = 0;
        try c.deposit{value: 0}(assets, receiver) returns (uint256 s) {
            reverted = false;
            returnedShares = s;
        } catch {
            reverted = true;
        }

