    C c;
    constructor(C _c) { c = _c; }

    // single entry that performs the property check
    function run(address caller, uint128 price) public payable {
        require(caller != address(0), "invalid caller");

        // Give authorization to this contract deployer inside C by calling rely from the constructor of C.
        // The test environment deploys C with its deployer ward set; here msg.sender is this test contract.
        // We test two scenarios: (1) if this contract is authorized, updatePrice must set latestPrice and lastPriceUpdate;
        // (2) if not authorized, calling updatePrice must revert.

        // Read state before the call
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // Attempt the call as this contract (message sender is InvMutTest), but we emulate authorized vs unauthorized by
        // using the provided `caller` parameter: if caller equals address(this) then we will call updatePrice normally
        // (this contract is the sender); otherwise, we attempt to call updatePrice via a low-level call encoding msg.sender = caller
        // However, due to the environment constraints (the checker will execute run once), we cannot change msg.sender for calls.
        // Instead, we use the fact that only callers with wards==1 can call updatePrice. We branch on whether this contract is authorized
        // by trying the call and catching reverts.

        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // General rule to assert:
        // If the call did not revert, then latestPrice must equal the provided price and lastPriceUpdate must be >= beforeTimestamp
        // (it should be updated to the current block time which is >= previous). If the call reverted, state must be unchanged.
        assert(
            (!reverted && afterPrice == price && afterTimestamp >= beforeTimestamp) ||
            (reverted && afterPrice == beforePrice && afterTimestamp == beforeTimestamp)
        );
    }

    receive() external payable {}
}

