    // We test that calling transfer/transferFrom/approve on C either reverts or returns true.
    // Single public entry taking parameters to drive different calls. We encode which of the
    // three functions to call via an index: 0=transfer,1=transferFrom,2=approve.
    function run(uint8 which, address toOrSpender, uint256 amount, address fromForTransferFrom) public payable {
        require(which <= 2, "which out of range");

        bool reverted;
        bool result = false;

        if (which == 0) {
            // call transfer(address,uint256)
            try c.transfer(toOrSpender, amount) returns (bool r) {
                reverted = false;
                result = r;
            } catch {
                reverted = true;
            }
        } else if (which == 1) {
            // call transferFrom(address,address,uint256)
            try c.transferFrom(fromForTransferFrom, toOrSpender, amount) returns (bool r) {
                reverted = false;
                result = r;
            } catch {
                reverted = true;
            }
        } else {
            // which == 2: call approve(address,uint256)
            try c.approve(toOrSpender, amount) returns (bool r) {
                reverted = false;
                result = r;
            } catch {
                reverted = true;
            }
        }

        // General rule: If the proxied call did not revert, it must return true.
        // (This encodes the ERC20 expectation that these functions return true on success.)
        assert(reverted || result == true);
    }

    receive() external payable {}
}

