        // the assetsEquivalent <= totalAssetsBefore + assets (the deposit can't make the vault report more assets than it had plus the deposited amount via convertToAssets mapping).
        assert(reverted || assetsEquivalent <= totalAssetsBefore + assets);
    }

    receive() external payable { }
}

