    constructor(C _c) { c = _c; }

    // Test: calling requestDeposit(...) from this contract either succeeds, or if it reverts
    // then totalAssets() is unchanged.
    function run(address owner, uint256 assets) public payable {
        require(owner != address(0));

        // Observe before-state via public view
        uint256 beforeTotal = c.totalAssets();

        bool reverted;
        // Top-level state-changing call; capture whether it reverts
        try c.requestDeposit(assets, owner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalAssets();

        // General rule: if the wrapper call reverted, totalAssets() must be unchanged
        assert(!reverted || afterTotal == beforeTotal);
    }

    receive() external payable {}
}

