contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property-based check
    function run(address caller, uint128 price) public payable {
        require(true);

        // Ensure caller is non-zero to avoid trivial address(0) edgecases in external calls
        // (the checker provides arbitrary addresses; we just avoid constraining further)
        // We will try both authorized and unauthorized invocation using rely/deny from c via this contract's auth.

        // Initially this contract (the deployer) was made an authorized ward in C's constructor.
        // Use that authority to set caller's authorization flag to 1, then test behavior, then revoke and test revert.

        // Grant authorization to `caller`
        c.rely(caller);

        // Perform the updatePrice call as the authorized address `caller` by invoking via low-level call from this contract.
        // Since the checker will execute the run function with msg.sender being an EOA, and calls on c will have msg.sender==address(this),
        // we must simulate a call from `caller` by performing a low-level call that encodes the function selector and uses `caller` as the executor
        // This cannot be done directly because msg.sender for calls from here will always be address(this).
        // Instead, we check the observable effects when this contract (which is initially authorized) calls updatePrice,
        // and also check that after denying this contract, calling updatePrice reverts.

        // Read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // As authorized (this contract is authorized in C.constructor), calling updatePrice should succeed and set latestPrice and timestamp
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // capture after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // Now revoke this contract's authorization and ensure updatePrice reverts for unauthorized caller
        c.deny(address(this));
        bool revertedAfterDeny;
        try c.updatePrice(price) {
            revertedAfterDeny = false;
        } catch {
            revertedAfterDeny = true;
        }

        // General rule (single assert):
        // If the initial call did not revert then latestPrice must equal the provided price and lastPriceUpdate must be > beforeTimestamp.
        // Additionally, after denying this contract, further calls must revert (i.e., revertedAfterDeny == true).
        assert((reverted == true && afterPrice == beforePrice && afterTimestamp == beforeTimestamp && revertedAfterDeny == true)
               || (reverted == false && afterPrice == price && afterTimestamp > beforeTimestamp && revertedAfterDeny == true));
    }

    receive() external payable {}
}

