contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry performing several actions driven by inputs
    function run(address receiver, uint256 amountOrShares, uint8 mode) public payable {
        require(receiver != address(0), "zero receiver");
        // mode: 0=deposit,1=mint,2=withdraw,3=redeem
        require(mode <= 3, "bad mode");

        // We will attempt the chosen call and observe whether it reverted
        bool reverted;
        uint256 returnedValue = type(uint256).max; // sentinel if reverted

        // Calls that change state must be top-level statements. Use try/catch to capture revert.
        if (mode == 0) {
            // deposit(uint256 assets, address receiver) returns (uint256 shares)
            try c.deposit(amountOrShares, receiver) returns (uint256 shares) {
                reverted = false;
                returnedValue = shares;
            } catch {
                reverted = true;
            }
        } else if (mode == 1) {
            // mint(uint256 shares, address receiver) returns (uint256 assets)
            try c.mint(amountOrShares, receiver) returns (uint256 assets) {
                reverted = false;
                returnedValue = assets;
            } catch {
                reverted = true;
            }
        } else if (mode == 2) {
            // withdraw(uint256 assets, address receiver, address owner) returns (uint256 shares)
            // use receiver as owner as well for simplicity
            try c.withdraw(amountOrShares, receiver, receiver) returns (uint256 shares) {
                reverted = false;
                returnedValue = shares;
            } catch {
                reverted = true;
            }
        } else {
            // redeem(uint256 shares, address receiver, address owner) returns (uint256 assets)
            try c.redeem(amountOrShares, receiver, receiver) returns (uint256 assets) {
                reverted = false;
                returnedValue = assets;
            } catch {
                reverted = true;
            }
        }

        // Read some public views after the call
        uint256 totalAssets = c.totalAssets();
        uint256 totalSupply = c.totalSupply();

        // General rule to assert:
        // If the call reverted, returnedValue is unchanged (we flagged reverted==true).
        // If the call did NOT revert, the returnedValue must be finite (not sentinel) and
        // consistent with convertToShares/convertToAssets: either returnedValue equals
        // convertToShares(amountOrShares) for deposit, or equals convertToAssets(amountOrShares) for mint,
        // or equals convertToShares(amountOrShares) for withdraw (shares redeemed), or equals convertToAssets(amountOrShares) for redeem.
        // We express this as a single assert combining the four modes.

        // compute the expected conversions using public view functions
        uint256 convShares = c.convertToShares(amountOrShares);
        uint256 convAssets = c.convertToAssets(amountOrShares);

        // Build the condition: if reverted true then returnedValue is sentinel (unchanged), otherwise returnedValue equals the matching conversion
        bool ok;
        if (reverted) {
            ok = (returnedValue == type(uint256).max);
        } else {
            if (mode == 0) {
                ok = (returnedValue == convShares);
            } else if (mode == 1) {
                ok = (returnedValue == convAssets);
            } else if (mode == 2) {
                ok = (returnedValue == convShares);
            } else {
                ok = (returnedValue == convAssets);
            }
        }

        // final assert: also ensure views are well-formed numbers (non-zero or zero allowed) — include them so assert is over observed values
        assert(ok && totalSupply >= 0 && totalAssets >= 0);
    }

    receive() external payable {}
}

