contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller will attempt to call updatePrice via this contract's address (msg.sender == address(this)).
    // We provide a flag `makeAuthorized` to optionally make this contract an authorized ward by calling rely from the original deployer (which is ward of c at construction time).
    function run(bool makeAuthorized, uint128 price) public payable {
        require(price > 0 || price == 0, true);

        // At construction of C, deployer (the test runner) was set as ward. Our test contract can only make itself authorized
        // by calling c.rely(address(this)) via that ward account. But msg.sender for calls here is the test caller, not the original deployer.
        // However, c.rely is public auth so only existing wards can call it. The freshly deployed C had wards[msg.sender]=1 for its deployer,
        // which is NOT this contract. So normally we cannot call rely. To allow both branches we attempt the rely call and catch revert.

        bool authorizedBefore;
        // read wards mapping via public getter: wards(address) is not explicitly declared, but Auth has public mapping so getter exists.
        // However mapping getter name is wards. Use try/catch in external to detect if call reverts when not allowed.
        try c.wards(address(this)) returns (uint256 v) {
            authorizedBefore = (v == 1);
        } catch {
            // If the getter somehow reverts (shouldn't), treat as unauthorized
            authorizedBefore = false;
        }

        // If requested, try to become authorized by invoking rely. This will succeed only if this contract is already authorized.
        // We perform it as a top-level state-changing call, catching reverts.
        bool relyReverted;
        try c.rely(address(this)) {
            relyReverted = false;
        } catch {
            relyReverted = true;
        }

        // Read latestPrice and lastPriceUpdate before the update attempt
        uint128 priceBefore = c.latestPrice();
        uint256 lastUpdateBefore = c.lastPriceUpdate();

        // Attempt the updatePrice call and record whether it reverted.
        bool updateReverted;
        try c.updatePrice(price) {
            updateReverted = false;
        } catch {
            updateReverted = true;
        }

        // Read after-values (if call reverted, values should be unchanged)
        uint128 priceAfter = c.latestPrice();
        uint256 lastUpdateAfter = c.lastPriceUpdate();

        // The general rule asserted below:
        // If updatePrice did not revert, then caller must have been authorized (wards[this]==1) either before or after our rely attempt,
        // and latestPrice equals the provided price and lastPriceUpdate was set to a non-decreasing timestamp >= before value.
        // If updatePrice reverted, then either the caller was unauthorized and the call reverted, or some other failure occurred.
        // We express this as: (not updateReverted) implies ( (authorizedBefore || !relyReverted) && priceAfter == price && lastUpdateAfter >= lastUpdateBefore )
        // and (updateReverted) implies priceAfter == priceBefore && lastUpdateAfter == lastUpdateBefore (state unchanged on revert).

        assert((!updateReverted && (authorizedBefore || !relyReverted) && priceAfter == price && lastUpdateAfter >= lastUpdateBefore)
               || (updateReverted && priceAfter == priceBefore && lastUpdateAfter == lastUpdateBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to become authorized (may revert). Then call updatePrice(price) and check the general invariant:
    // either the call reverted and state is unchanged, or it succeeded, the caller was authorized, latestPrice == price,
    // and lastPriceUpdate is >= previous lastPriceUpdate.
    function run(uint128 price) public payable {
        // no precondition on price

        // record before-values
        uint128 priceBefore = c.latestPrice();
        uint256 lastUpdateBefore = c.lastPriceUpdate();

        // Attempt to call rely(address(this)) to become authorized; record whether it reverted.
        bool relyReverted;
        try c.rely(address(this)) {
            relyReverted = false;
        } catch {
            relyReverted = true;
        }

        // Attempt the updatePrice call and record whether it reverted.
        bool updateReverted;
        try c.updatePrice(price) {
            updateReverted = false;
        } catch {
            updateReverted = true;
        }

        // read after-values
        uint128 priceAfter = c.latestPrice();
        uint256 lastUpdateAfter = c.lastPriceUpdate();

        // check whether this contract is currently authorized according to the public wards getter
        bool authorizedNow;
        try c.wards(address(this)) returns (uint256 v) {
            authorizedNow = (v == 1);
        } catch {
            authorizedNow = false;
        }

        // General invariant:
        // - If updatePrice reverted, state must be unchanged.
        // - If updatePrice succeeded, then contract must be authorized (either before or after rely attempt),
        //   latestPrice equals the provided price, and lastPriceUpdate is >= previous value.
        assert(
            (updateReverted && priceAfter == priceBefore && lastUpdateAfter == lastUpdateBefore)
            || (!updateReverted && authorizedNow && priceAfter == price && lastUpdateAfter >= lastUpdateBefore)
        );
    }

    receive() external payable {}
}

